package com.Senai.Mubak.service; import java.time.LocalDate; import java.util.*; import jakarta.annotation.PostConstruct; import org.springframework.stereotype.Service; import com.Senai.Mubak.model.*; import com.Senai.Mubak.repository.UsuarioRepository; /** Regras de usuários: cria ROOT inicial, cadastra clientes e autentica por e-mail ou documento. */ @Service public class UsuarioService {final UsuarioRepository r; final SenhaService s; public UsuarioService(UsuarioRepository r,SenhaService s){this.r=r;this.s=s;} @PostConstruct public void root(){if(r.findByEmailIgnoreCase("root@root.local").isEmpty()) rootUser("root","root");} public Usuario rootUser(String n,String p){Usuario u=new Usuario();u.setNome(n);u.setEmail(n+"@root.local");u.setDocumento("00000000000");u.setDataNascimento(LocalDate.of(1970,1,1));u.setPerfil("ROOT");u.setSenhaHash(s.hash(p));return r.save(u);} public Usuario cadastrar(UsuarioForm f){if(!DocumentoValidator.valido(f.getDocumento()))throw new IllegalArgumentException("CPF ou CNPJ inválido.");if(!f.getEmail().equalsIgnoreCase(f.getConfirmacaoEmail()))throw new IllegalArgumentException("Os e-mails não conferem.");if(!f.getSenha().equals(f.getConfirmacaoSenha()))throw new IllegalArgumentException("As senhas não conferem.");Usuario u=new Usuario();u.setNome(f.getNome().trim());u.setDocumento(DocumentoValidator.digits(f.getDocumento()));u.setDataNascimento(f.getDataNascimento());u.setEmail(f.getEmail().trim().toLowerCase());u.setPerfil("CLIENTE");u.setSenhaHash(s.hash(f.getSenha()));return r.save(u);} public Usuario login(String i,String p){Usuario u=i.equalsIgnoreCase("root")?r.findByEmailIgnoreCase("root@root.local").orElse(null):i.contains("@")?r.findByEmailIgnoreCase(i).orElse(null):r.findByDocumento(DocumentoValidator.digits(i)).orElse(null);if(u==null||!s.hash(p).equals(u.getSenhaHash()))throw new IllegalArgumentException();return u;} public List<Usuario> listar(){return r.findAll();}}